import{_ as d,o as a,c as e,a5 as o}from"./chunks/framework.CXroN2RO.js";const g=JSON.parse('{"title":"三大コンパイラ: MSVC・Clang・GCC","description":"","frontmatter":{"title":"三大コンパイラ: MSVC・Clang・GCC","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"C++には主要な処理系が3つあり、ゲーム開発では複数と付き合うのが普通です(Windows=MSVC、コンソール機=Clangベースが多い、Linuxサーバー=GCC/Clang)。標準準拠の共通部分と、処理系ごとの差分(フラグ・拡張・ABI)を分けて把握します。"}},"headers":[],"relativePath":"tools/build/compilers.md","filePath":"tools/build/compilers.md"}'),l={name:"tools/build/compilers.md"};function r(n,t,i,c,s,C){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="三大コンパイラ-msvc・clang・gcc" tabindex="-1">三大コンパイラ: MSVC・Clang・GCC <a class="header-anchor" href="#三大コンパイラ-msvc・clang・gcc" aria-label="Permalink to &quot;三大コンパイラ: MSVC・Clang・GCC&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>C++には主要な処理系が3つあり、<strong>ゲーム開発では複数と付き合うのが普通</strong>です(Windows=MSVC、コンソール機=Clangベースが多い、Linuxサーバー=GCC/Clang)。標準準拠の共通部分と、処理系ごとの差分(フラグ・拡張・ABI)を分けて把握します。</p><h2 id="_3つのプロフィール" tabindex="-1">3つのプロフィール <a class="header-anchor" href="#_3つのプロフィール" aria-label="Permalink to &quot;3つのプロフィール&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>MSVC</th><th>Clang</th><th>GCC</th></tr></thead><tbody><tr><td>開発元</td><td>Microsoft</td><td>LLVMプロジェクト</td><td>GNU</td></tr><tr><td>主戦場</td><td>Windows / Visual Studio</td><td>Mac(Apple Clang)、Android、多くのコンソール機、ツール基盤</td><td>Linux、組み込み</td></tr><tr><td>コンパイラ実行体</td><td>cl.exe</td><td>clang++</td><td>g++</td></tr><tr><td>C++20対応</td><td>良好(近年は最速級で対応)</td><td>良好</td><td>良好</td></tr><tr><td>エラーメッセージ</td><td>改善中</td><td><strong>最良と評判</strong>(初学者に優しい)</td><td>良</td></tr><tr><td>特徴</td><td>VSデバッガとの統合、Windows SDK連携</td><td>ツール化(clang-format/clang-tidyの基盤)、モジュール構造</td><td>歴史と実績、最適化の強さ</td></tr></tbody></table><ul><li><strong>Clangのツール性</strong>が現代の要: フォーマッタ(clang-format)、静的解析(clang-tidy)、言語サーバー(clangd = VSCodeの補完)はすべてClangの解析器の再利用。MSVCで開発していてもClangツール群は使う</li><li>コンソール機のコンパイラはNDA下だが、Clangベースが多いのは公知(だからクロスプラットフォームコードはClangでも警告ゼロにしておくと移植が楽)</li></ul><h2 id="フラグの対応表-日常で使うもの" tabindex="-1">フラグの対応表(日常で使うもの) <a class="header-anchor" href="#フラグの対応表-日常で使うもの" aria-label="Permalink to &quot;フラグの対応表(日常で使うもの)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>GCC / Clang</th><th>MSVC</th></tr></thead><tbody><tr><td>規格指定</td><td><code>-std=c++20</code></td><td><code>/std:c++20</code></td></tr><tr><td>最適化</td><td><code>-O0 / -O2 / -O3 / -Os</code></td><td><code>/Od / /O2 / /O1</code></td></tr><tr><td>警告</td><td><code>-Wall -Wextra</code>(全部ではない点に注意)</td><td><code>/W4</code>(<code>/Wall</code>は過剰)</td></tr><tr><td>警告をエラーに</td><td><code>-Werror</code></td><td><code>/WX</code></td></tr><tr><td>デバッグ情報</td><td><code>-g</code></td><td><code>/Zi</code>(PDB生成)</td></tr><tr><td>define</td><td><code>-DNAME=1</code></td><td><code>/DNAME=1</code></td></tr><tr><td>例外オフ</td><td><code>-fno-exceptions</code></td><td><code>/EHs-c-</code>(既定で例外モデル指定<code>/EHsc</code>)</td></tr><tr><td>RTTIオフ</td><td><code>-fno-rtti</code></td><td><code>/GR-</code></td></tr><tr><td>サニタイザ</td><td><code>-fsanitize=address</code> 等</td><td><code>/fsanitize=address</code>(近年対応)</td></tr></tbody></table><h2 id="処理系差が現れる場所-ハマりどころ" tabindex="-1">処理系差が現れる場所(ハマりどころ) <a class="header-anchor" href="#処理系差が現れる場所-ハマりどころ" aria-label="Permalink to &quot;処理系差が現れる場所(ハマりどころ)&quot;">​</a></h2><ol><li><strong>ABIの互換性</strong>: MSVCとGCC(MinGW)のC++ ABIは一般に互換ではない。C ABIで契約をそろえた連携とは区別する(→ <a href="/study/runtime/cpp-internals/symbols-and-linkage.html">ABI</a>)。ClangはWindowsでMSVC互換を目指すclang-clを持つが、標準ライブラリ・CRT・設定を含む互換条件の確認は必要</li><li><strong>警告の検出範囲が違う</strong>: GCCで警告ゼロでもMSVCで出る(逆も)。<strong>複数コンパイラでビルドするだけでバグが見つかる</strong>のはこのため(CIで両方回す価値)</li><li>拡張機能: <code>#pragma once</code> は3社対応(事実上標準)だが、<code>__forceinline</code>(MSVC)/<code>__attribute__</code>(GCC/Clang)、可変長配列(GCC拡張。標準C++にはない)などは移植の罠</li><li>標準ライブラリも別物: MSVC STL / libstdc++(GCC) / libc++(Clang)。実装依存の挙動(unordered_mapの成長戦略、SSOの閾値等)が異なる(→ <a href="/study/languages/cpp/undefined-behavior.html">実装定義</a>)</li><li>最適化の癖・浮動小数点の厳密さ(<code>/fp:fast</code> vs <code>-ffast-math</code>)——クロスプラットフォームで<strong>リプレイ・ロックステップ同期が壊れる</strong>原因になりうる(決定性が要るなら固定小数点や厳密モードの検討)</li></ol><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><ul><li>現在の一般的なC#開発ではRoslynが広く使われるが、コンパイラや言語版、対象API、JIT/AOTといった実行方式の差がなくなるわけではない。UnityのIL2CPPは生成したC++を<strong>各プラットフォームのC++コンパイラ</strong>でビルドする。一般.NETで使えるライブラリが、そのままUnityの全バックエンドで使えるとも限らない(→ <a href="/study/languages/csharp/il2cpp.html">IL2CPP</a>、<a href="https://docs.unity.com/en-us/engine/6000.0/manual/programming-environment/overview-of-dot-net-in-unity/dotnet-profile-support" target="_blank" rel="noreferrer">UnityのAPI互換性</a>)</li><li>「Standalone/il2cppでだけ挙動が違う」報告の一部は、C++コンパイラ差・最適化差に由来する</li></ul><h2 id="実務指針" tabindex="-1">実務指針 <a class="header-anchor" href="#実務指針" aria-label="Permalink to &quot;実務指針&quot;">​</a></h2><ul><li><strong>1次コンパイラ</strong>(毎日使う)+<strong>CIで2次コンパイラ</strong>を回す構成が理想(警告・移植性の早期発見)</li><li>警告フラグはプロジェクト開始時に最大級で固定(後から上げると数千件出て詰む → <a href="/study/tools/build/debugging-and-analysis.html">警告レベル</a>)</li><li>コンパイラのバージョン更新はブランチで隔離してテスト(最適化差・新警告・ABI変化)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>3コンパイラの主戦場をそれぞれ言えますか。</li><li>「複数コンパイラでビルドするとバグが見つかる」のはなぜですか。</li><li>MinGW(GCC)でビルドした.libをVSプロジェクトで使えない理由は?</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>samples/ の任意のサンプルを <code>-Wall -Wextra</code> 付きでビルドし、警告が出るか確認してください。godbolt.orgで同じコードをGCC/Clang/MSVCでコンパイルし、生成コードとエラーメッセージの違いを見比べるのも推奨です。</p><hr><p>前: <a href="/study/tools/build/what-is-build.html">ビルドとは何か</a> | <a href="/study/tools/build/">カテゴリ目次</a> | 次: <a href="/study/tools/build/build-tools-cmake.html">ビルドツール: CMake</a></p>',20)])])}const u=d(l,[["render",r]]);export{g as __pageData,u as default};
